import app from './worker-v136.js';
import { SERVICE_NETWORK_SCHEMA_V137 } from './service-network-schema-v137.js';

const HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const CATEGORIES=new Set(['REPAIR','INSTALLATION','MAINTENANCE','DIAGNOSTIC','CLEANING','HOME_SERVICE','AUTOMOTIVE','ELECTRONICS','APPLIANCE','IT_SUPPORT','OTHER']);
const MODES=new Set(['REMOTE','AT_PROVIDER','AT_CUSTOMER','HYBRID']);
const PRICING=new Set(['QUOTE_REQUIRED','FIXED_FROM','HOURLY_FROM','DIAGNOSTIC_FIRST']);
const COVERAGE=new Set(['REMOTE','CITY','POSTAL_CODES','REGION','COUNTRY']);
const BOOKING_ACTIONS=new Set(['ACCEPT','DECLINE','SUGGEST_TIME','RESCHEDULE','CANCEL','NO_SHOW','START']);
const now=()=>new Date().toISOString();
const uid=p=>`${p}${crypto.randomUUID().replaceAll('-','')}`;
const publicId=p=>`${p}-${crypto.randomUUID().replaceAll('-','').slice(0,16).toUpperCase()}`;
const clean=(v,n=5000)=>String(v??'').replace(/\0/g,'').trim().slice(0,n);
const normalized=v=>clean(v,500).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const key=v=>normalized(v).replaceAll(' ','_').slice(0,100);
const json=(v,s=200,h={})=>new Response(JSON.stringify(v),{status:s,headers:{...HEADERS,...h}});
const safeJson=(v,fallback={})=>{try{return JSON.parse(v||'')}catch{return fallback}};
const list=(v,max=30,n=180)=>[...new Set((Array.isArray(v)?v:[]).map(x=>clean(x,n)).filter(Boolean))].slice(0,max);
const bool=v=>v===true||v===1||v==='1';
const int=(v,min,max)=>{const x=Number(v);return Number.isInteger(x)&&x>=min&&x<=max?x:null};
const cents=v=>v===null||v===undefined||v===''?null:int(v,0,1_000_000_000);
const currency=v=>/^[A-Z]{3}$/.test(clean(v,3).toUpperCase())?clean(v,3).toUpperCase():'EUR';
const dateTime=v=>{const x=clean(v,40);if(!x)return null;const d=new Date(x);return Number.isNaN(d.valueOf())?null:d.toISOString()};
const dateOnly=v=>{const x=clean(v,10);return /^\d{4}-\d{2}-\d{2}$/.test(x)?x:null};
function log(event,fields={}){console.log(JSON.stringify({scope:'still_services',event,at:now(),...fields}))}
async function sha(v){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(v)));return[...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function cookie(request,name){for(const part of(request.headers.get('cookie')||'').split(';')){const[k,...v]=part.trim().split('=');if(k===name)return decodeURIComponent(v.join('='))}return''}
async function buyerSession(request,env){const token=cookie(request,'still_buyer');if(!token)return null;return env.DB.prepare(`SELECT a.id buyer_account_id,a.email,a.name,a.email_verified FROM buyer_sessions s JOIN buyer_accounts a ON a.id=s.buyer_account_id WHERE s.token_hash=? AND s.expires_at>? AND a.status='active'`).bind(await sha(token),now()).first()}
async function companySession(request,env){const token=cookie(request,'still_company');if(!token)return null;return env.DB.prepare(`SELECT m.id member_id,m.email,m.role,o.id organization_id,o.name organization_name,o.status organization_status FROM merchant_sessions s JOIN merchant_members m ON m.id=s.member_id JOIN merchant_organizations o ON o.id=m.organization_id WHERE s.token_hash=? AND s.expires_at>? AND m.status='active'`).bind(await sha(token),now()).first()}
function sameOrigin(request){const origin=request.headers.get('origin');return!origin||origin===new URL(request.url).origin}
function rewrite(request,pathname){const u=new URL(request.url);u.pathname=pathname;u.search='';return new Request(u,{method:'GET',headers:request.headers})}
let schemaReady;
async function ensureSchema(env){if(!schemaReady)schemaReady=env.DB.batch(SERVICE_NETWORK_SCHEMA_V137.map(sql=>env.DB.prepare(sql))).catch(error=>{schemaReady=undefined;throw error});await schemaReady}
function eventStatement(env,{bookingId=null,briefId=null,providerId=null,actorType,eventType,details={}}){log(eventType,{bookingId,briefId,providerId});return env.DB.prepare(`INSERT INTO service_network_events(id,public_id,booking_id,brief_id,provider_id,actor_type,event_type,details_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('sne_'),publicId('SEV'),bookingId,briefId,providerId,actorType,eventType,JSON.stringify(details).slice(0,4000),now())}
function historyStatement(env,buyerId,entityType,entityId,eventType,title,details={},sourceId=null){return env.DB.prepare(`INSERT INTO world_history_events(id,public_id,buyer_account_id,entity_type,entity_public_id,event_type,title,details_json,source_type,source_public_id,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('whe_'),publicId('HIS'),buyerId,entityType,entityId,eventType,title,JSON.stringify(details).slice(0,4000),'service',sourceId,now(),now())}
function notifyStatement(env,buyerId,sourceKey,type,title,body,href){return env.DB.prepare(`INSERT OR IGNORE INTO professional_notifications(id,public_id,buyer_account_id,source_key,notification_type,title,body,href,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('pno_'),publicId('NTF'),buyerId,sourceKey,type,title,body||null,href,now())}
async function blocked(env,a,b){if(!a||!b)return false;const row=await env.DB.prepare(`SELECT 1 ok FROM market_blocks WHERE (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) OR (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) LIMIT 1`).bind(a,b,b,a).first();if(row)log('authorization_denied',{buyerId:a,targetBuyerId:b,reason:'service_block'});return!!row}

async function providerForActor(env,buyer,company){if(buyer){return env.DB.prepare(`SELECT p.*,pr.buyer_account_id provider_buyer_account_id,a.email_verified,0 organization_verified FROM service_network_providers p JOIN professional_profiles pr ON pr.id=p.professional_profile_id JOIN buyer_accounts a ON a.id=pr.buyer_account_id WHERE pr.buyer_account_id=?`).bind(buyer.buyer_account_id).first()}if(company){return env.DB.prepare(`SELECT p.*,NULL provider_buyer_account_id,0 email_verified,(o.status='verified') organization_verified FROM service_network_providers p JOIN merchant_organizations o ON o.id=p.organization_id WHERE p.organization_id=?`).bind(company.organization_id).first()}return null}
async function providerByPublic(env,id){return env.DB.prepare(`SELECT p.*,pr.buyer_account_id provider_buyer_account_id,a.email_verified,(o.status='verified') organization_verified FROM service_network_providers p LEFT JOIN professional_profiles pr ON pr.id=p.professional_profile_id LEFT JOIN buyer_accounts a ON a.id=pr.buyer_account_id LEFT JOIN merchant_organizations o ON o.id=p.organization_id WHERE p.public_id=?`).bind(id).first()}
function providerJson(row,{privateView=false}={}){if(!row)return null;return{publicId:row.public_id,type:row.provider_type,displayName:row.display_name,description:row.description||null,coarseLocation:row.coarse_location||null,acceptingRequests:!!row.accepting_requests,active:!!row.active,identityTrust:row.provider_type==='BUSINESS'?(row.organization_verified?'VERIFIED_ORGANIZATION':'UNVERIFIED_ORGANIZATION'):(row.email_verified?'VERIFIED_EMAIL':'DECLARED_IDENTITY'),serviceClaims:'PROVIDER_DECLARED',...(privateView?{canPublish:row.provider_type==='BUSINESS'?!!row.organization_verified:!!row.email_verified}:{}),createdAt:row.created_at,updatedAt:row.updated_at}}
function capabilityJson(row){return{publicId:row.public_id,key:row.capability_key,name:row.name,category:row.category,serviceModes:safeJson(row.service_modes_json,[]),pricingModel:row.pricing_model,startingPriceCents:row.starting_price_cents,currency:row.currency,coverageType:row.coverage_type,coverage:safeJson(row.coverage_json,{}),brandCompatibility:safeJson(row.brand_compatibility_json,[]),description:row.description||null,active:!!row.active,declarationStatus:row.declaration_status}}
async function capabilities(env,providerId){const rows=await env.DB.prepare(`SELECT * FROM service_network_capabilities WHERE provider_id=? ORDER BY active DESC,name`).bind(providerId).all();return(rows.results||[]).map(capabilityJson)}
async function availability(env,providerId){const rows=await env.DB.prepare(`SELECT public_id,starts_at,ends_at,status FROM service_network_availability WHERE provider_id=? AND ends_at>? ORDER BY starts_at LIMIT 180`).bind(providerId,now()).all();return rows.results||[]}
async function saveProvider(request,env,buyer,company){const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);let current=await providerForActor(env,buyer,company),originId,providerType,displayName,canPublish=false;if(buyer){const profile=await env.DB.prepare(`SELECT * FROM professional_profiles WHERE buyer_account_id=?`).bind(buyer.buyer_account_id).first();if(!profile?.professional_mode_enabled)return json({error:'professional_mode_required'},409);originId=profile.id;providerType='PROFESSIONAL';displayName=clean(body.displayName||current?.display_name||profile.display_name,120);canPublish=!!buyer.email_verified}else if(company){originId=company.organization_id;providerType='BUSINESS';displayName=clean(body.displayName||current?.display_name||company.organization_name,120);canPublish=company.organization_status==='verified'}else return json({error:'unauthorized'},401);if(displayName.length<2)return json({error:'display_name_required'},422);const requested=bool(body.active??current?.active),active=requested&&canPublish,ts=now();if(current)await env.DB.prepare(`UPDATE service_network_providers SET display_name=?,description=?,coarse_location=?,accepting_requests=?,active=?,updated_at=? WHERE id=?`).bind(displayName,clean(body.description??current.description,1800)||null,clean(body.coarseLocation??current.coarse_location,160)||null,bool(body.acceptingRequests??current.accepting_requests)?1:0,active?1:0,ts,current.id).run();else await env.DB.prepare(`INSERT INTO service_network_providers(id,public_id,provider_type,professional_profile_id,organization_id,display_name,description,coarse_location,accepting_requests,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('snp_'),publicId('SRV'),providerType,providerType==='PROFESSIONAL'?originId:null,providerType==='BUSINESS'?originId:null,displayName,clean(body.description,1800)||null,clean(body.coarseLocation,160)||null,bool(body.acceptingRequests)?1:0,active?1:0,ts,ts).run();current=await providerForActor(env,buyer,company);log('service_provider_enabled',{providerId:current.public_id,providerType,active,requested,eligibility:canPublish});return json({ok:true,provider:providerJson(current,{privateView:true}),capabilities:await capabilities(env,current.id),notice:requested&&!active?'Provider profile saved, but publication requires the existing identity verification.':null},current.created_at===ts?201:200)}
async function saveCapability(request,env,provider){const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const name=clean(body.name,140),capKey=key(body.key||name),category=clean(body.category,40).toUpperCase(),modes=list(body.serviceModes,4,30).map(x=>x.toUpperCase()).filter(x=>MODES.has(x)),pricing=clean(body.pricingModel,40).toUpperCase(),coverage=clean(body.coverageType,30).toUpperCase();if(name.length<2||!capKey)return json({error:'capability_name_required'},422);if(!CATEGORIES.has(category)||!modes.length||!PRICING.has(pricing)||!COVERAGE.has(coverage))return json({error:'invalid_service_capability'},422);if(pricing==='QUOTE_REQUIRED'&&body.startingPriceCents!==undefined&&body.startingPriceCents!==null)return json({error:'starting_price_not_allowed_for_quote_required'},422);const coverageData=body.coverage&&typeof body.coverage==='object'?body.coverage:{};const ts=now(),existing=await env.DB.prepare(`SELECT id FROM service_network_capabilities WHERE provider_id=? AND capability_key=?`).bind(provider.id,capKey).first();if(existing)return json({error:'capability_exists'},409);await env.DB.prepare(`INSERT INTO service_network_capabilities(id,public_id,provider_id,capability_key,name,category,service_modes_json,pricing_model,starting_price_cents,currency,coverage_type,coverage_json,brand_compatibility_json,description,active,declaration_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,'PROVIDER_DECLARED',?,?)`).bind(uid('snc_'),publicId('SCP'),provider.id,capKey,name,category,JSON.stringify(modes),pricing,cents(body.startingPriceCents),currency(body.currency),coverage,JSON.stringify(coverageData).slice(0,2000),JSON.stringify(list(body.brandCompatibility,50,100)),clean(body.description,1200)||null,ts,ts).run();log('service_capability_created',{providerId:provider.public_id,capabilityKey:capKey});return json({ok:true,capabilities:await capabilities(env,provider.id)},201)}
async function addAvailability(request,env,provider){const body=await request.json().catch(()=>null),start=dateTime(body?.startsAt),end=dateTime(body?.endsAt);if(!start||!end||end<=start||start<=now())return json({error:'invalid_availability_window'},422);const conflict=await env.DB.prepare(`SELECT 1 ok FROM service_network_availability WHERE provider_id=? AND status='OFFERED' AND starts_at<? AND ends_at>? LIMIT 1`).bind(provider.id,end,start).first();if(conflict)return json({error:'availability_overlap'},409);const pid=publicId('SLT'),ts=now();await env.DB.prepare(`INSERT INTO service_network_availability(id,public_id,provider_id,starts_at,ends_at,status,created_at,updated_at) VALUES(?,?,?,?,?,'OFFERED',?,?)`).bind(uid('sna_'),pid,provider.id,start,end,ts,ts).run();return json({ok:true,slotId:pid,availability:await availability(env,provider.id)},201)}

async function needForOwner(env,buyerId,id){return env.DB.prepare(`SELECT n.*,p.public_id thing_public_id,p.title thing_title,tp.manufacturer brand,tp.model FROM world_needs n LEFT JOIN ownership_passports p ON p.id=n.thing_passport_id LEFT JOIN world_thing_profiles tp ON tp.passport_id=p.id WHERE n.buyer_account_id=? AND n.public_id=?`).bind(buyerId,id).first()}
async function briefForOwner(env,buyerId,needId){return env.DB.prepare(`SELECT b.*,n.public_id need_public_id,p.public_id thing_public_id,p.title thing_title FROM service_network_briefs b JOIN world_needs n ON n.id=b.need_id LEFT JOIN ownership_passports p ON p.id=b.thing_passport_id WHERE b.buyer_account_id=? AND b.need_id=?`).bind(buyerId,needId).first()}
async function briefAttachments(env,briefId){const rows=await env.DB.prepare(`SELECT d.public_id,d.title,d.document_type,d.mime_type,d.file_bytes FROM service_network_brief_attachments a JOIN world_documents d ON d.id=a.document_id WHERE a.brief_id=? AND d.archived_at IS NULL ORDER BY a.created_at`).bind(briefId).all();return rows.results||[]}
function briefJson(row,attachments=[]){if(!row)return null;return{publicId:row.public_id,needId:row.need_public_id,thingId:row.thing_public_id||null,thingTitle:row.thing_title||null,title:row.title,issueDescription:row.issue_description,category:row.category,serviceMode:row.service_mode,coarseLocation:row.coarse_location||null,brand:row.brand||null,model:row.model||null,desiredWindowStart:row.desired_window_start||null,desiredWindowEnd:row.desired_window_end||null,addressRequired:!!row.address_required,approvedFields:safeJson(row.approved_fields_json,[]),confirmedAt:row.confirmed_at||null,matchingEnabled:!!row.matching_enabled,attachments,privacy:{exactAddressShared:false,otherThingsShared:false,privateNotesShared:false},createdAt:row.created_at,updatedAt:row.updated_at}}
async function saveBrief(request,env,buyer,needPublicId){const need=await needForOwner(env,buyer.buyer_account_id,needPublicId);if(!need)return json({error:'need_not_found'},404);if(!['REPAIR','SERVICE','MAINTAIN','BOOK','HIRE'].includes(need.need_type))return json({error:'service_need_required'},409);if(['RESOLVED','DISMISSED','CANCELLED'].includes(need.status))return json({error:'need_not_editable'},409);const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const current=await briefForOwner(env,buyer.buyer_account_id,need.id),title=clean(body.title??current?.title??need.title,180),issue=clean(body.issueDescription??current?.issue_description??need.problem_description??need.description??need.title,3000),category=clean(body.category??current?.category??need.category??'REPAIR',40).toUpperCase(),mode=clean(body.serviceMode??current?.service_mode??need.location_mode??'AT_PROVIDER',30).toUpperCase();if(title.length<2||issue.length<2||!CATEGORIES.has(category)||!MODES.has(mode))return json({error:'invalid_service_brief'},422);const start=body.desiredWindowStart===undefined?current?.desired_window_start:dateTime(body.desiredWindowStart),end=body.desiredWindowEnd===undefined?current?.desired_window_end:dateTime(body.desiredWindowEnd);if((start&&!end)||(!start&&end)||(start&&end&&end<=start))return json({error:'invalid_desired_window'},422);const approvedFields=list(body.approvedFields??safeJson(current?.approved_fields_json,[]),20,80).filter(x=>['thing_name','brand','model','purchase_date','warranty_status','service_history'].includes(x));const confirmed=bool(body.confirmed),matching=confirmed&&bool(body.matchingEnabled),ts=now(),id=current?.id||uid('snb_'),pid=current?.public_id||publicId('SBR');if(current)await env.DB.prepare(`UPDATE service_network_briefs SET title=?,issue_description=?,category=?,service_mode=?,coarse_location=?,brand=?,model=?,desired_window_start=?,desired_window_end=?,address_required=?,approved_fields_json=?,confirmed_at=?,matching_enabled=?,updated_at=? WHERE id=?`).bind(title,issue,category,mode,clean(body.coarseLocation??current.coarse_location,160)||null,clean(body.brand??current.brand??need.brand,120)||null,clean(body.model??current.model??need.model,120)||null,start||null,end||null,bool(body.addressRequired??current.address_required)?1:0,JSON.stringify(approvedFields),confirmed?(current.confirmed_at||ts):null,matching?1:0,ts,id).run();else await env.DB.prepare(`INSERT INTO service_network_briefs(id,public_id,need_id,buyer_account_id,thing_passport_id,title,issue_description,category,service_mode,coarse_location,brand,model,desired_window_start,desired_window_end,address_required,approved_fields_json,confirmed_at,matching_enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,pid,need.id,buyer.buyer_account_id,need.thing_passport_id,title,issue,category,mode,clean(body.coarseLocation,160)||null,clean(body.brand??need.brand,120)||null,clean(body.model??need.model,120)||null,start||null,end||null,bool(body.addressRequired)?1:0,JSON.stringify(approvedFields),confirmed?ts:null,matching?1:0,ts,ts).run();if(body.address){const a=body.address,address=clean(a.addressLine,240),city=clean(a.city,120),country=clean(a.countryCode,2).toUpperCase();if(!address||!city||!/^[A-Z]{2}$/i.test(country))return json({error:'invalid_private_address'},422);await env.DB.prepare(`INSERT INTO service_network_addresses(brief_id,buyer_account_id,address_line,postal_code,city,country_code,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(brief_id) DO UPDATE SET address_line=excluded.address_line,postal_code=excluded.postal_code,city=excluded.city,country_code=excluded.country_code,updated_at=excluded.updated_at`).bind(id,buyer.buyer_account_id,address,clean(a.postalCode,30)||null,city,country,ts).run()}if(Array.isArray(body.attachmentIds)){await env.DB.prepare(`DELETE FROM service_network_brief_attachments WHERE brief_id=?`).bind(id).run();for(const documentId of list(body.attachmentIds,12,40)){const doc=await env.DB.prepare(`SELECT id FROM world_documents WHERE buyer_account_id=? AND public_id=? AND archived_at IS NULL`).bind(buyer.buyer_account_id,documentId).first();if(!doc)return json({error:'attachment_not_found',documentId},404);await env.DB.prepare(`INSERT INTO service_network_brief_attachments(id,brief_id,document_id,approved_at,created_at) VALUES(?,?,?,?,?)`).bind(uid('sba_'),id,doc.id,ts,ts).run()}}log('service_brief_created',{briefId:pid,needId:needPublicId,confirmed,matching});return json({ok:true,brief:briefJson(await briefForOwner(env,buyer.buyer_account_id,need.id),await briefAttachments(env,id))},current?200:201)}

function coverageMatches(cap,brief){if(cap.coverage_type==='REMOTE')return brief.service_mode==='REMOTE'||brief.service_mode==='HYBRID';const coverage=safeJson(cap.coverage_json,{}),location=normalized(brief.coarse_location);if(!location)return false;if(cap.coverage_type==='CITY')return list(coverage.cities,100,120).some(x=>location.includes(normalized(x)));if(cap.coverage_type==='POSTAL_CODES')return list(coverage.postalCodes,100,30).some(x=>location.includes(normalized(x)));if(cap.coverage_type==='REGION')return list(coverage.regions,100,120).some(x=>location.includes(normalized(x)));if(cap.coverage_type==='COUNTRY')return list(coverage.countries,50,80).some(x=>location.includes(normalized(x)));return false}
function brandMatches(cap,brief){const brands=safeJson(cap.brand_compatibility_json,[]).map(normalized);return!brands.length||!brief.brand||brands.includes(normalized(brief.brand))}
async function generateMatches(env,buyer,needPublicId,url){const need=await needForOwner(env,buyer.buyer_account_id,needPublicId);if(!need)return json({error:'need_not_found'},404);const brief=await briefForOwner(env,buyer.buyer_account_id,need.id);if(!brief?.confirmed_at||!brief.matching_enabled)return json({error:'confirmed_service_brief_required'},409);const limit=Math.min(int(url.searchParams.get('limit'),1,20)||10,10),rows=await env.DB.prepare(`SELECT p.*,c.id capability_id,c.public_id capability_public_id,c.capability_key,c.name capability_name,c.category capability_category,c.service_modes_json,c.pricing_model,c.starting_price_cents,c.currency capability_currency,c.coverage_type,c.coverage_json,c.brand_compatibility_json,c.declaration_status,pr.buyer_account_id provider_buyer_account_id,a.email_verified,(o.status='verified') organization_verified FROM service_network_providers p JOIN service_network_capabilities c ON c.provider_id=p.id LEFT JOIN professional_profiles pr ON pr.id=p.professional_profile_id LEFT JOIN buyer_accounts a ON a.id=pr.buyer_account_id LEFT JOIN merchant_organizations o ON o.id=p.organization_id WHERE p.active=1 AND p.accepting_requests=1 AND c.active=1 AND c.category=? AND NOT EXISTS(SELECT 1 FROM market_blocks mb WHERE (mb.blocker_buyer_account_id=? AND mb.blocked_buyer_account_id=pr.buyer_account_id) OR (mb.blocker_buyer_account_id=pr.buyer_account_id AND mb.blocked_buyer_account_id=?)) ORDER BY p.public_id,c.public_id`).bind(brief.category,buyer.buyer_account_id,buyer.buyer_account_id).all();const matches=[];for(const row of rows.results||[]){const modes=safeJson(row.service_modes_json,[]),failed=[],reasons=[];if(modes.includes(brief.service_mode))reasons.push(`Offers ${brief.service_mode.toLowerCase().replaceAll('_',' ')} service`);else failed.push('service_mode');if(coverageMatches(row,brief))reasons.push('Declared coverage matches the shared area');else failed.push('coverage');if(brandMatches(row,brief))reasons.push(brief.brand?'Declared compatible brand':'No brand restriction declared');else failed.push('brand');if(brief.desired_window_start){const slot=await env.DB.prepare(`SELECT public_id FROM service_network_availability WHERE provider_id=? AND status='OFFERED' AND starts_at<? AND ends_at>? LIMIT 1`).bind(row.id,brief.desired_window_end,brief.desired_window_start).first();if(slot)reasons.push('A real offered slot overlaps the requested window');else failed.push('availability_window')}if(failed.length)continue;const score=60+(brief.brand?15:5)+(brief.desired_window_start?15:5);await env.DB.prepare(`INSERT INTO service_network_matches(id,brief_id,provider_id,capability_id,match_score,reasons_json,failed_constraints_json,generated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(brief_id,provider_id,capability_id) DO UPDATE SET match_score=excluded.match_score,reasons_json=excluded.reasons_json,failed_constraints_json=excluded.failed_constraints_json,generated_at=excluded.generated_at`).bind(uid('snm_'),brief.id,row.id,row.capability_id,score,JSON.stringify(reasons),JSON.stringify(failed),now()).run();matches.push({provider:providerJson(row),capability:{publicId:row.capability_public_id,name:row.capability_name,category:row.capability_category,serviceModes:modes,pricingModel:row.pricing_model,startingPriceCents:row.starting_price_cents,currency:row.capability_currency,coverageType:row.coverage_type,declarationStatus:row.declaration_status},matchScore:score,matchReasons:reasons,failedConstraints:[]})}matches.sort((a,b)=>b.matchScore-a.matchScore||a.provider.publicId.localeCompare(b.provider.publicId));log('provider_match_generated',{briefId:brief.public_id,count:matches.length});return json({matches:matches.slice(0,limit),zeroResult:matches.length?null:{message:'No real matching service providers are available yet.',actions:['Adjust service brief','Continue externally','Invite a provider','Save Need']}})}

async function inviteProvider(request,env,buyer,needPublicId){const need=await needForOwner(env,buyer.buyer_account_id,needPublicId),brief=need&&await briefForOwner(env,buyer.buyer_account_id,need.id);if(!brief?.confirmed_at)return json({error:'confirmed_service_brief_required'},409);const body=await request.json().catch(()=>null),contact=clean(body?.contact,254);if(!contact)return json({error:'contact_required'},422);const pid=publicId('INV');await env.DB.prepare(`INSERT INTO service_network_invites(id,public_id,buyer_account_id,brief_id,contact,invitation_note,status,created_at) VALUES(?,?,?,?,?,?,'SENT',?)`).bind(uid('sni_'),pid,buyer.buyer_account_id,brief.id,contact,clean(body.invitationNote,800)||null,now()).run();return json({ok:true,invite:{publicId:pid,status:'SENT'},notice:'This invitation does not create a provider, availability, quote, or booking.'},201)}
async function requestQuote(request,env,buyer,needPublicId){const need=await needForOwner(env,buyer.buyer_account_id,needPublicId),brief=need&&await briefForOwner(env,buyer.buyer_account_id,need.id);if(!brief?.confirmed_at||!brief.matching_enabled)return json({error:'confirmed_service_brief_required'},409);const body=await request.json().catch(()=>null),provider=await providerByPublic(env,clean(body?.providerId,40));if(!provider?.active||!provider.accepting_requests)return json({error:'provider_not_available'},409);if(await blocked(env,buyer.buyer_account_id,provider.provider_buyer_account_id))return json({error:'blocked'},403);const capability=await env.DB.prepare(`SELECT * FROM service_network_capabilities WHERE provider_id=? AND public_id=? AND active=1`).bind(provider.id,clean(body.capabilityId,40)).first();if(!capability)return json({error:'capability_not_found'},404);const match=await env.DB.prepare(`SELECT id FROM service_network_matches WHERE brief_id=? AND provider_id=? AND capability_id=?`).bind(brief.id,provider.id,capability.id).first();if(!match)return json({error:'provider_match_required'},409);const ts=now(),id=uid('snq_'),pid=publicId('QRE');try{await env.DB.prepare(`INSERT INTO service_network_quote_requests(id,public_id,brief_id,provider_id,capability_id,buyer_account_id,status,diagnostic_first,message,created_at,updated_at) VALUES(?,?,?,?,?,?,'SENT',?,?,?,?)`).bind(id,pid,brief.id,provider.id,capability.id,buyer.buyer_account_id,capability.pricing_model==='DIAGNOSTIC_FIRST'?1:0,clean(body.message,1000)||null,ts,ts).run()}catch(error){if(String(error).includes('UNIQUE'))return json({error:'quote_already_requested'},409);throw error}if(provider.provider_buyer_account_id)await notifyStatement(env,provider.provider_buyer_account_id,`service-quote:${pid}`,'SERVICE_QUOTE_REQUEST','New service quote request',brief.title,`/app/work/service/requests/${pid}`).run();await eventStatement(env,{briefId:brief.id,providerId:provider.id,actorType:'CLIENT',eventType:'quote_request_sent',details:{quoteRequestId:pid}}).run();return json({ok:true,quoteRequest:{publicId:pid,status:'SENT',diagnosticFirst:capability.pricing_model==='DIAGNOSTIC_FIRST'}},201)}

async function quoteRequestForProvider(env,id,providerId){return env.DB.prepare(`SELECT q.*,b.public_id brief_public_id,b.title brief_title,b.issue_description,b.category,b.service_mode,b.coarse_location,b.brand,b.model,b.desired_window_start,b.desired_window_end,c.public_id capability_public_id,c.name capability_name FROM service_network_quote_requests q JOIN service_network_briefs b ON b.id=q.brief_id JOIN service_network_capabilities c ON c.id=q.capability_id WHERE q.public_id=? AND q.provider_id=?`).bind(id,providerId).first()}
async function createQuote(request,env,provider,requestId){const qr=await quoteRequestForProvider(env,requestId,provider.id);if(!qr)return json({error:'quote_request_not_found'},404);if(!['SENT','VIEWED'].includes(qr.status))return json({error:'quote_request_not_open'},409);const body=await request.json().catch(()=>null),scope=clean(body?.scope,3000),type=clean(body?.pricingType,40).toUpperCase();if(scope.length<2||!['FIXED','ESTIMATE','DIAGNOSTIC_FIRST'].includes(type))return json({error:'invalid_quote'},422);const amount=cents(body.amountCents),diagnostic=cents(body.diagnosticFeeCents);if(type==='FIXED'&&amount===null)return json({error:'fixed_amount_required'},422);if(type==='DIAGNOSTIC_FIRST'&&diagnostic===null)return json({error:'diagnostic_fee_required'},422);const ts=now(),id=uid('snz_'),pid=publicId('SQT');await env.DB.batch([env.DB.prepare(`INSERT INTO service_network_quotes(id,public_id,quote_request_id,provider_id,buyer_account_id,amount_cents,currency,pricing_type,diagnostic_fee_cents,scope,estimated_duration_minutes,valid_until,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'SENT',?,?)`).bind(id,pid,qr.id,provider.id,qr.buyer_account_id,amount,currency(body.currency),type,diagnostic,scope,int(body.estimatedDurationMinutes,1,100000),dateOnly(body.validUntil),ts,ts),env.DB.prepare(`UPDATE service_network_quote_requests SET status='QUOTED',updated_at=? WHERE id=?`).bind(ts,qr.id),notifyStatement(env,qr.buyer_account_id,`service-quote:${pid}`,'SERVICE_QUOTE_CREATED','Service quote received',qr.brief_title,`/app/work/service/quotes/${pid}`),eventStatement(env,{briefId:qr.brief_id,providerId:provider.id,actorType:'PROVIDER',eventType:'service_quote_created',details:{quoteId:pid,pricingType:type}})]);return json({ok:true,quote:{publicId:pid,status:'SENT',pricingType:type,amountCents:amount,diagnosticFeeCents:diagnostic,currency:currency(body.currency),scope}},201)}
async function quotesForNeed(env,buyer,needId){const need=await needForOwner(env,buyer.buyer_account_id,needId);if(!need)return json({error:'need_not_found'},404);const rows=await env.DB.prepare(`SELECT z.public_id,z.amount_cents,z.currency,z.pricing_type,z.diagnostic_fee_cents,z.scope,z.estimated_duration_minutes,z.valid_until,z.status,z.created_at,p.public_id provider_public_id,p.display_name provider_name,c.public_id capability_public_id,c.name capability_name FROM service_network_quotes z JOIN service_network_quote_requests q ON q.id=z.quote_request_id JOIN service_network_briefs b ON b.id=q.brief_id JOIN service_network_providers p ON p.id=z.provider_id JOIN service_network_capabilities c ON c.id=q.capability_id WHERE b.need_id=? AND z.buyer_account_id=? ORDER BY z.created_at DESC`).bind(need.id,buyer.buyer_account_id).all();return json({quotes:rows.results||[],paymentNotice:'Quotes are informational. Payment is arranged externally; Still does not hold funds or provide escrow.'})}

async function bookingForParticipant(env,id,buyer,company){const row=await env.DB.prepare(`SELECT k.*,b.public_id brief_public_id,b.title brief_title,b.issue_description,b.coarse_location,b.address_required,b.buyer_account_id client_id,n.public_id need_public_id,n.thing_passport_id,p.public_id provider_public_id,p.display_name provider_name,p.provider_type,p.professional_profile_id,p.organization_id,c.public_id capability_public_id,c.name capability_name,c.category,q.public_id quote_public_id,q.amount_cents,q.currency quote_currency,q.pricing_type FROM service_network_bookings k JOIN service_network_briefs b ON b.id=k.brief_id JOIN world_needs n ON n.id=b.need_id JOIN service_network_providers p ON p.id=k.provider_id JOIN service_network_capabilities c ON c.id=k.capability_id LEFT JOIN service_network_quotes q ON q.id=k.quote_id WHERE k.public_id=?`).bind(id).first();if(!row)return null;const provider=await providerForActor(env,buyer,company);const client=!!buyer&&row.buyer_account_id===buyer.buyer_account_id,providerAccess=provider?.id===row.provider_id;if(!client&&!providerAccess){log('authorization_denied',{bookingId:id,reason:'not_participant'});return null}return{...row,viewerRole:client?'CLIENT':'PROVIDER',providerActor:provider}}
async function bookingPayload(env,row){const [messages,report,parts,attachments,slot,address]=await Promise.all([env.DB.prepare(`SELECT public_id,actor_type,body,created_at FROM service_network_booking_messages WHERE booking_id=? ORDER BY created_at`).bind(row.id).all(),env.DB.prepare(`SELECT * FROM service_network_reports WHERE booking_id=?`).bind(row.id).first(),env.DB.prepare(`SELECT p.* FROM service_network_report_parts p JOIN service_network_reports r ON r.id=p.report_id WHERE r.booking_id=? ORDER BY p.created_at`).bind(row.id).all(),env.DB.prepare(`SELECT d.public_id,d.title,d.document_type,d.mime_type,d.file_bytes FROM service_network_booking_attachments a JOIN world_documents d ON d.id=a.document_id WHERE a.booking_id=? AND d.archived_at IS NULL`).bind(row.id).all(),row.availability_id?env.DB.prepare(`SELECT public_id,starts_at,ends_at,status FROM service_network_availability WHERE id=?`).bind(row.availability_id).first():Promise.resolve(null),row.status==='CONFIRMED'||['IN_PROGRESS','REPORT_SUBMITTED','COMPLETED'].includes(row.status)?env.DB.prepare(`SELECT address_line,postal_code,city,country_code FROM service_network_addresses WHERE brief_id=?`).bind(row.brief_id).first():Promise.resolve(null)]);if(address)log('address_revealed',{bookingId:row.public_id,viewerRole:row.viewerRole});return{booking:{publicId:row.public_id,status:row.status,viewerRole:row.viewerRole,brief:{publicId:row.brief_public_id,title:row.brief_title,issueDescription:row.issue_description,coarseLocation:row.coarse_location,needId:row.need_public_id},provider:{publicId:row.provider_public_id,name:row.provider_name,type:row.provider_type},capability:{publicId:row.capability_public_id,name:row.capability_name,category:row.category},serviceMode:row.service_mode,scheduledStart:row.scheduled_start,scheduledEnd:row.scheduled_end,slot,quote:row.quote_public_id?{publicId:row.quote_public_id,amountCents:row.amount_cents,currency:row.quote_currency,pricingType:row.pricing_type}:null,payment:{mode:'EXTERNAL_MANUAL',status:row.payment_status,notice:'Payment is arranged outside Still. Still does not hold funds or provide escrow.'},address:address||null,addressVisibility:address?'Revealed to booking participants after confirmation.':'Hidden until the booking is confirmed.',providerNote:row.provider_note||null,clientNote:row.client_note||null,startedAt:row.started_at||null,completedAt:row.completed_at||null,createdAt:row.created_at,updatedAt:row.updated_at},messages:messages.results||[],attachments:attachments.results||[],report:report?{publicId:report.public_id,summary:report.summary,workPerformed:report.work_performed,diagnosis:report.diagnosis||null,recommendations:report.recommendations||null,serviceWarrantyDays:report.service_warranty_days,warrantyTerms:report.warranty_terms||null,status:report.status,submittedAt:report.submitted_at,confirmedAt:report.confirmed_at||null,parts:parts.results||[]}:null}}
async function createBooking(request,env,buyer){const body=await request.json().catch(()=>null),quote=body?.quoteId?await env.DB.prepare(`SELECT z.*,q.brief_id,q.capability_id,q.buyer_account_id,p.public_id provider_public_id,b.service_mode FROM service_network_quotes z JOIN service_network_quote_requests q ON q.id=z.quote_request_id JOIN service_network_providers p ON p.id=z.provider_id JOIN service_network_briefs b ON b.id=q.brief_id WHERE z.public_id=? AND z.buyer_account_id=? AND z.status='SENT'`).bind(clean(body.quoteId,40),buyer.buyer_account_id).first():null;if(body?.quoteId&&!quote)return json({error:'quote_not_found'},404);let brief,provider,capability;if(quote){brief=await env.DB.prepare(`SELECT * FROM service_network_briefs WHERE id=?`).bind(quote.brief_id).first();provider=await env.DB.prepare(`SELECT * FROM service_network_providers WHERE id=?`).bind(quote.provider_id).first();capability=await env.DB.prepare(`SELECT * FROM service_network_capabilities WHERE id=?`).bind(quote.capability_id).first()}else{brief=await env.DB.prepare(`SELECT * FROM service_network_briefs WHERE public_id=? AND buyer_account_id=? AND confirmed_at IS NOT NULL`).bind(clean(body?.briefId,40),buyer.buyer_account_id).first();provider=brief&&await providerByPublic(env,clean(body.providerId,40));capability=provider&&await env.DB.prepare(`SELECT * FROM service_network_capabilities WHERE provider_id=? AND public_id=? AND active=1`).bind(provider.id,clean(body.capabilityId,40)).first()}if(!brief||!provider||!capability||!provider.active||!provider.accepting_requests)return json({error:'booking_context_unavailable'},409);if(await blocked(env,buyer.buyer_account_id,provider.provider_buyer_account_id))return json({error:'blocked'},403);const slot=body.availabilityId?await env.DB.prepare(`SELECT * FROM service_network_availability WHERE public_id=? AND provider_id=? AND status='OFFERED' AND ends_at>?`).bind(clean(body.availabilityId,40),provider.id,now()).first():null;if(body.availabilityId&&!slot)return json({error:'availability_not_found'},404);const start=slot?.starts_at||dateTime(body.scheduledStart),end=slot?.ends_at||dateTime(body.scheduledEnd);if((start&&!end)||(!start&&end)||(start&&end&&end<=start))return json({error:'invalid_booking_window'},422);if(brief.address_required&&!await env.DB.prepare(`SELECT 1 ok FROM service_network_addresses WHERE brief_id=?`).bind(brief.id).first())return json({error:'private_address_required'},422);const ts=now(),id=uid('snk_'),pid=publicId('BKG');await env.DB.batch([env.DB.prepare(`INSERT INTO service_network_bookings(id,public_id,brief_id,provider_id,capability_id,quote_id,buyer_account_id,availability_id,service_mode,status,scheduled_start,scheduled_end,client_note,payment_mode,payment_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'REQUESTED',?,?,?,'EXTERNAL_MANUAL','NOT_RECORDED',?,?)`).bind(id,pid,brief.id,provider.id,capability.id,quote?.id||null,buyer.buyer_account_id,slot?.id||null,brief.service_mode,start||null,end||null,clean(body.clientNote,1000)||null,ts,ts),quote?env.DB.prepare(`UPDATE service_network_quotes SET status='ACCEPTED',updated_at=? WHERE id=?`).bind(ts,quote.id):env.DB.prepare(`SELECT 1`),eventStatement(env,{bookingId:id,briefId:brief.id,providerId:provider.id,actorType:'CLIENT',eventType:'booking_requested',details:{bookingId:pid}}),historyStatement(env,buyer.buyer_account_id,'need',(await env.DB.prepare(`SELECT public_id FROM world_needs WHERE id=?`).bind(brief.need_id).first()).public_id,'service.booking_requested','Service booking requested',{bookingId:pid,provider:provider.display_name},pid)]);if(provider.provider_buyer_account_id)await notifyStatement(env,provider.provider_buyer_account_id,`service-booking:${pid}`,'SERVICE_BOOKING_REQUESTED','New booking request',brief.title,`/app/work/service/booking/${pid}`).run();return json({ok:true,bookingId:pid,status:'REQUESTED',paymentNotice:'Payment is external/manual. No deposit or escrow has been created.'},201)}
async function mirrorCompanyBooking(env,row){if(row.provider_type!=='BUSINESS'||!row.organization_id)return;let service=await env.DB.prepare(`SELECT id FROM service_catalog WHERE organization_id=? AND name=? AND active=1 LIMIT 1`).bind(row.organization_id,row.capability_name).first();const ts=now();if(!service){service={id:uid('svc_')};await env.DB.prepare(`INSERT INTO service_catalog(id,organization_id,name,category,description,default_duration_minutes,delivery_mode,recurring_allowed,active,created_at,updated_at) VALUES(?,?,?,?,?,NULL,?,0,1,?,?)`).bind(service.id,row.organization_id,row.capability_name,row.category,'Created from the organization’s published Still service capability.',row.service_mode==='REMOTE'?'remote':row.service_mode==='AT_CUSTOMER'?'customer_location':row.service_mode==='HYBRID'?'hybrid':'onsite',ts,ts).run()}const exists=await env.DB.prepare(`SELECT id FROM service_engagements WHERE organization_id=? AND reference=?`).bind(row.organization_id,row.public_id).first();if(!exists)await env.DB.prepare(`INSERT INTO service_engagements(id,public_id,organization_id,service_id,customer_email,customer_name,status,scheduled_start,scheduled_end,location_text,reference,price_amount,currency,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,'confirmed',?,?,?,?,?,?,?, ?,?)`).bind(uid('eng_'),publicId('SE'),row.organization_id,service.id,null,null,row.scheduled_start,row.scheduled_end,row.coarse_location||null,row.public_id,row.amount_cents===null?null:Number(row.amount_cents)/100,row.quote_currency||'EUR','Still service-network booking. Customer contact remains in the participant-scoped booking.',ts,ts).run()}
async function bookingAction(request,env,row,action){const body=await request.json().catch(()=>({})),role=row.viewerRole,current=row.status,ts=now();let next=current,event=null;if(action==='ACCEPT'&&role==='PROVIDER'&&current==='REQUESTED'){next='CONFIRMED';event='booking_confirmed'}else if(action==='DECLINE'&&role==='PROVIDER'&&current==='REQUESTED'){next='DECLINED';event='booking_cancelled'}else if(action==='SUGGEST_TIME'&&role==='PROVIDER'&&['REQUESTED','CONFIRMED'].includes(current)){const start=dateTime(body.scheduledStart),end=dateTime(body.scheduledEnd);if(!start||!end||end<=start)return json({error:'invalid_suggested_time'},422);await env.DB.prepare(`UPDATE service_network_bookings SET scheduled_start=?,scheduled_end=?,status='TIME_SUGGESTED',provider_note=?,updated_at=? WHERE id=?`).bind(start,end,clean(body.note,1000)||null,ts,row.id).run();event='booking_rescheduled';next='TIME_SUGGESTED'}else if(action==='RESCHEDULE'&&['CLIENT','PROVIDER'].includes(role)&&['CONFIRMED','TIME_SUGGESTED'].includes(current)){const start=dateTime(body.scheduledStart),end=dateTime(body.scheduledEnd);if(!start||!end||end<=start)return json({error:'invalid_reschedule'},422);await env.DB.prepare(`UPDATE service_network_bookings SET scheduled_start=?,scheduled_end=?,status=?,updated_at=? WHERE id=?`).bind(start,end,role==='CLIENT'?'REQUESTED':'TIME_SUGGESTED',ts,row.id).run();event='booking_rescheduled';next=role==='CLIENT'?'REQUESTED':'TIME_SUGGESTED'}else if(action==='CANCEL'&&['REQUESTED','CONFIRMED','TIME_SUGGESTED'].includes(current)){if(clean(body.reason,1000).length<2)return json({error:'cancellation_reason_required'},422);next='CANCELLED';event='booking_cancelled'}else if(action==='NO_SHOW'&&role==='PROVIDER'&&current==='CONFIRMED'){next='NO_SHOW';event='booking_cancelled'}else if(action==='START'&&role==='PROVIDER'&&current==='CONFIRMED'){next='IN_PROGRESS';event='service_started'}else return json({error:'invalid_booking_transition'},409);if(next!==current&&!['TIME_SUGGESTED','REQUESTED'].includes(next))await env.DB.prepare(`UPDATE service_network_bookings SET status=?,provider_note=CASE WHEN ?='PROVIDER' THEN COALESCE(?,provider_note) ELSE provider_note END,client_note=CASE WHEN ?='CLIENT' THEN COALESCE(?,client_note) ELSE client_note END,started_at=CASE WHEN ?='IN_PROGRESS' THEN ? ELSE started_at END,cancelled_at=CASE WHEN ? IN ('CANCELLED','DECLINED','NO_SHOW') THEN ? ELSE cancelled_at END,updated_at=? WHERE id=?`).bind(next,role,clean(body.note||body.reason,1000)||null,role,clean(body.note||body.reason,1000)||null,next,ts,next,ts,ts,row.id).run();await eventStatement(env,{bookingId:row.id,briefId:row.brief_id,providerId:row.provider_id,actorType:role,eventType:event,details:{from:current,to:next}}).run();if(next==='CONFIRMED'){if(row.availability_id)await env.DB.prepare(`UPDATE service_network_availability SET status='BOOKED',updated_at=? WHERE id=?`).bind(ts,row.availability_id).run();await mirrorCompanyBooking(env,{...row,status:next});log('address_revealed',{bookingId:row.public_id,reason:'booking_confirmed'})}const recipient=role==='CLIENT'?row.provider_buyer_account_id:row.buyer_account_id;if(recipient)await notifyStatement(env,recipient,`service-booking:${row.public_id}:${next}`,'SERVICE_BOOKING_UPDATED',`Booking ${next.toLowerCase().replaceAll('_',' ')}`,row.brief_title,`/app/work/service/booking/${row.public_id}`).run();return json({ok:true,status:next})}
async function bookingMessage(request,env,row){if(await blocked(env,row.buyer_account_id,row.provider_buyer_account_id))return json({error:'blocked'},403);const body=await request.json().catch(()=>null),text=clean(body?.body,4000);if(!text)return json({error:'message_required'},422);const pid=publicId('MSG');await env.DB.prepare(`INSERT INTO service_network_booking_messages(id,public_id,booking_id,actor_type,actor_buyer_account_id,actor_organization_id,body,created_at) VALUES(?,?,?,?,?,?,?,?)`).bind(uid('snm_'),pid,row.id,row.viewerRole,row.viewerRole==='CLIENT'?row.buyer_account_id:row.provider_buyer_account_id,row.viewerRole==='PROVIDER'?row.organization_id:null,text,now()).run();return json({ok:true,messageId:pid},201)}
async function createReport(request,env,row){if(row.viewerRole!=='PROVIDER'||row.status!=='IN_PROGRESS')return json({error:'provider_in_progress_booking_required'},409);const body=await request.json().catch(()=>null),summary=clean(body?.summary,1000),work=clean(body?.workPerformed,4000);if(summary.length<2||work.length<2)return json({error:'report_fields_required'},422);const parts=Array.isArray(body.parts)?body.parts.slice(0,100):[];for(const p of parts)if(clean(p.name,180).length<2||int(p.quantity,1,10000)===null)return json({error:'invalid_report_part'},422);const ts=now(),id=uid('snr_'),pid=publicId('SRP'),statements=[env.DB.prepare(`INSERT INTO service_network_reports(id,public_id,booking_id,provider_id,summary,work_performed,diagnosis,recommendations,service_warranty_days,warranty_terms,status,submitted_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'SUBMITTED',?,?,?)`).bind(id,pid,row.id,row.provider_id,summary,work,clean(body.diagnosis,2000)||null,clean(body.recommendations,2000)||null,int(body.serviceWarrantyDays,0,3650),clean(body.warrantyTerms,2000)||null,ts,ts,ts),env.DB.prepare(`UPDATE service_network_bookings SET status='REPORT_SUBMITTED',updated_at=? WHERE id=?`).bind(ts,row.id),eventStatement(env,{bookingId:row.id,briefId:row.brief_id,providerId:row.provider_id,actorType:'PROVIDER',eventType:'service_report_created',details:{reportId:pid}}),notifyStatement(env,row.buyer_account_id,`service-report:${pid}`,'SERVICE_REPORT_CREATED','Service report ready for review',row.brief_title,`/app/work/service/booking/${row.public_id}`)];for(const p of parts)statements.push(env.DB.prepare(`INSERT INTO service_network_report_parts(id,public_id,report_id,name,part_number,quantity,unit_cost_cents,currency,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(uid('srp_'),publicId('PRT'),id,clean(p.name,180),clean(p.partNumber,120)||null,int(p.quantity,1,10000),cents(p.unitCostCents),currency(p.currency),clean(p.notes,500)||null,ts));await env.DB.batch(statements);return json({ok:true,reportId:pid,status:'REPORT_SUBMITTED'},201)}
async function confirmService(env,row){if(row.viewerRole!=='CLIENT'||row.status!=='REPORT_SUBMITTED')return json({error:'client_report_review_required'},409);const report=await env.DB.prepare(`SELECT * FROM service_network_reports WHERE booking_id=? AND status='SUBMITTED'`).bind(row.id).first();if(!report)return json({error:'service_report_not_found'},404);const ts=now(),outcomeId=uid('wro_'),outcomePid=publicId('OUT'),statements=[env.DB.prepare(`UPDATE service_network_reports SET status='CONFIRMED',confirmed_at=?,updated_at=? WHERE id=?`).bind(ts,ts,report.id),env.DB.prepare(`UPDATE service_network_bookings SET status='COMPLETED',completed_at=?,updated_at=? WHERE id=?`).bind(ts,ts,row.id),env.DB.prepare(`UPDATE world_needs SET status='RESOLVED',resolved_at=?,updated_at=? WHERE id=(SELECT need_id FROM service_network_briefs WHERE id=?) AND buyer_account_id=?`).bind(ts,ts,row.brief_id,row.buyer_account_id),env.DB.prepare(`INSERT INTO world_resolution_outcomes(id,public_id,buyer_account_id,need_id,resolution_type,summary,cost_cents,currency,related_thing_passport_id,provider_name,feedback,resolved_at,created_at,updated_at) VALUES(?,?,?,(SELECT need_id FROM service_network_briefs WHERE id=?),'REPAIR',?,?,?,(SELECT thing_passport_id FROM service_network_briefs WHERE id=?),?,NULL,?,?,?)`).bind(outcomeId,outcomePid,row.buyer_account_id,row.brief_id,report.summary,row.amount_cents,row.quote_currency||'EUR',row.brief_id,row.provider_name,ts,ts,ts),historyStatement(env,row.buyer_account_id,'need',row.need_public_id,'service.completed','Service completed',{bookingId:row.public_id,provider:row.provider_name,reportId:report.public_id},row.public_id),eventStatement(env,{bookingId:row.id,briefId:row.brief_id,providerId:row.provider_id,actorType:'CLIENT',eventType:'service_confirmed',details:{reportId:report.public_id}}),eventStatement(env,{bookingId:row.id,briefId:row.brief_id,providerId:row.provider_id,actorType:'SYSTEM',eventType:'need_resolved',details:{needId:row.need_public_id,outcomeId:outcomePid}})];if(row.thing_passport_id)statements.push(historyStatement(env,row.buyer_account_id,'thing',(await env.DB.prepare(`SELECT public_id FROM ownership_passports WHERE id=?`).bind(row.thing_passport_id).first())?.public_id||row.need_public_id,'thing.service_completed',`Service completed: ${row.capability_name}`,{bookingId:row.public_id,provider:row.provider_name,reportId:report.public_id,serviceWarrantyDays:report.service_warranty_days},row.public_id));await env.DB.batch(statements);return json({ok:true,status:'COMPLETED',resolutionOutcomeId:outcomePid})}
async function favoriteProvider(env,row){if(row.viewerRole!=='CLIENT'||row.status!=='COMPLETED')return json({error:'completed_client_booking_required'},409);await env.DB.prepare(`INSERT INTO service_network_favorites(buyer_account_id,provider_id,source_booking_id,created_at) VALUES(?,?,?,?) ON CONFLICT(buyer_account_id,provider_id) DO UPDATE SET source_booking_id=excluded.source_booking_id,created_at=excluded.created_at`).bind(row.buyer_account_id,row.provider_id,row.id,now()).run();return json({ok:true,favorite:true,providerId:row.provider_public_id})}
async function repeatBooking(env,row){if(row.viewerRole!=='CLIENT'||row.status!=='COMPLETED')return json({error:'completed_client_booking_required'},409);const ts=now(),id=uid('snk_'),pid=publicId('BKG');await env.DB.prepare(`INSERT INTO service_network_bookings(id,public_id,brief_id,provider_id,capability_id,buyer_account_id,service_mode,status,client_note,payment_mode,payment_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'REQUESTED','Repeat service request','EXTERNAL_MANUAL','NOT_RECORDED',?,?)`).bind(id,pid,row.brief_id,row.provider_id,row.capability_id,row.buyer_account_id,row.service_mode,ts,ts).run();await eventStatement(env,{bookingId:id,briefId:row.brief_id,providerId:row.provider_id,actorType:'CLIENT',eventType:'booking_requested',details:{repeatOf:row.public_id}}).run();return json({ok:true,bookingId:pid,status:'REQUESTED'},201)}

async function providerWork(env,provider){const [requests,bookings,slots]=await Promise.all([env.DB.prepare(`SELECT q.public_id,q.status,q.diagnostic_first,q.message,q.created_at,b.title,b.category,b.service_mode,b.coarse_location,b.brand,b.model,c.name capability_name FROM service_network_quote_requests q JOIN service_network_briefs b ON b.id=q.brief_id JOIN service_network_capabilities c ON c.id=q.capability_id WHERE q.provider_id=? ORDER BY q.updated_at DESC LIMIT 100`).bind(provider.id).all(),env.DB.prepare(`SELECT k.public_id,k.status,k.scheduled_start,k.scheduled_end,k.service_mode,k.updated_at,b.title,p.display_name provider_name,c.name capability_name FROM service_network_bookings k JOIN service_network_briefs b ON b.id=k.brief_id JOIN service_network_providers p ON p.id=k.provider_id JOIN service_network_capabilities c ON c.id=k.capability_id WHERE k.provider_id=? ORDER BY k.updated_at DESC LIMIT 100`).bind(provider.id).all(),availability(env,provider.id)]);return{provider:providerJson(provider,{privateView:true}),capabilities:await capabilities(env,provider.id),quoteRequests:requests.results||[],bookings:bookings.results||[],availability:slots}}

async function handleApi(request,env,ctx,url,buyer,company){const path=url.pathname;let match;const provider=await providerForActor(env,buyer,company);if(path==='/api/v1/services/provider'){if(request.method==='GET')return json({provider:providerJson(provider,{privateView:true}),capabilities:provider?await capabilities(env,provider.id):[],availability:provider?await availability(env,provider.id):[]});if(['POST','PATCH'].includes(request.method))return saveProvider(request,env,buyer,company)}if(path==='/api/v1/services/provider/capabilities'){if(!provider)return json({error:'service_provider_required'},409);if(request.method==='GET')return json({capabilities:await capabilities(env,provider.id)});if(request.method==='POST')return saveCapability(request,env,provider)}if(path==='/api/v1/services/provider/availability'){if(!provider)return json({error:'service_provider_required'},409);if(request.method==='GET')return json({availability:await availability(env,provider.id)});if(request.method==='POST')return addAvailability(request,env,provider)}if(path==='/api/v1/services/provider/work'&&request.method==='GET'){if(!provider)return json({error:'service_provider_required'},409);return json(await providerWork(env,provider))}match=path.match(/^\/api\/v1\/services\/quote-requests\/([^/]+)\/quotes$/);if(match&&request.method==='POST'){if(!provider)return json({error:'service_provider_required'},409);return createQuote(request,env,provider,decodeURIComponent(match[1]))}if(path==='/api/v1/services/bookings'&&request.method==='POST'){if(!buyer)return json({error:'buyer_required'},403);return createBooking(request,env,buyer)}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)$/);if(match&&request.method==='GET'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);return row?json(await bookingPayload(env,row)):json({error:'not_found'},404)}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)\/(accept|decline|suggest-time|reschedule|cancel|no-show|start)$/);if(match&&request.method==='POST'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);if(!row)return json({error:'not_found'},404);return bookingAction(request,env,row,match[2].replaceAll('-','_').toUpperCase())}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)\/messages$/);if(match&&request.method==='POST'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);return row?bookingMessage(request,env,row):json({error:'not_found'},404)}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)\/report$/);if(match&&request.method==='POST'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);return row?createReport(request,env,row):json({error:'not_found'},404)}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)\/confirm$/);if(match&&request.method==='POST'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);return row?confirmService(env,row):json({error:'not_found'},404)}match=path.match(/^\/api\/v1\/services\/bookings\/([^/]+)\/(favorite|repeat)$/);if(match&&request.method==='POST'){const row=await bookingForParticipant(env,decodeURIComponent(match[1]),buyer,company);if(!row)return json({error:'not_found'},404);return match[2]==='favorite'?favoriteProvider(env,row):repeatBooking(env,row)}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/service-brief$/);if(match){if(!buyer)return json({error:'buyer_required'},403);const need=await needForOwner(env,buyer.buyer_account_id,decodeURIComponent(match[1]));if(!need)return json({error:'need_not_found'},404);if(request.method==='GET'){const brief=await briefForOwner(env,buyer.buyer_account_id,need.id);return json({brief:brief?briefJson(brief,await briefAttachments(env,brief.id)):null})}if(request.method==='POST')return saveBrief(request,env,buyer,decodeURIComponent(match[1]))}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/service-matches$/);if(match&&request.method==='GET'){if(!buyer)return json({error:'buyer_required'},403);return generateMatches(env,buyer,decodeURIComponent(match[1]),url)}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/service-invites$/);if(match&&request.method==='POST'){if(!buyer)return json({error:'buyer_required'},403);return inviteProvider(request,env,buyer,decodeURIComponent(match[1]))}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/service-quote-requests$/);if(match&&request.method==='POST'){if(!buyer)return json({error:'buyer_required'},403);return requestQuote(request,env,buyer,decodeURIComponent(match[1]))}match=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/service-quotes$/);if(match&&request.method==='GET'){if(!buyer)return json({error:'buyer_required'},403);return quotesForNeed(env,buyer,decodeURIComponent(match[1]))}return null}

async function augmentNow(request,env,ctx,buyer){const base=await app.fetch(rewrite(request,'/api/v1/world/now'),env,ctx),data=await base.clone().json().catch(()=>({}));if(!base.ok)return base;const rows=await env.DB.prepare(`SELECT k.public_id,k.status,k.scheduled_start,k.updated_at,b.title,p.display_name provider_name FROM service_network_bookings k JOIN service_network_briefs b ON b.id=k.brief_id JOIN service_network_providers p ON p.id=k.provider_id WHERE k.buyer_account_id=? AND k.status NOT IN ('COMPLETED','CANCELLED','DECLINED','NO_SHOW') ORDER BY COALESCE(k.scheduled_start,k.updated_at) LIMIT 20`).bind(buyer.buyer_account_id).all();return json({...data,services:{bookings:rows.results||[],active:(rows.results||[]).length}})}

export default{async fetch(request,env,ctx){const url=new URL(request.url),path=url.pathname,isNewService=path.startsWith('/api/v1/services/provider')||path.startsWith('/api/v1/services/bookings')||path.startsWith('/api/v1/services/quote-requests')||/^\/api\/v1\/world\/needs\/[^/]+\/service-/.test(path),nowRoute=path==='/api/v1/world/now'&&request.method==='GET';if(!isNewService&&!nowRoute)return app.fetch(request,env,ctx);try{const [buyer,company]=await Promise.all([buyerSession(request,env),companySession(request,env)]);if(!buyer&&!company)return json({error:'unauthorized'},401);if(!['GET','HEAD'].includes(request.method)&&!sameOrigin(request))return json({error:'origin_not_allowed'},403);if(buyer){const warm=await app.fetch(rewrite(request,'/api/v1/world/needs'),env,ctx);if(!warm.ok&&warm.status!==404)return warm}await ensureSchema(env);if(nowRoute){if(!buyer)return json({error:'buyer_required'},403);return augmentNow(request,env,ctx,buyer)}const response=await handleApi(request,env,ctx,url,buyer,company);return response||app.fetch(request,env,ctx)}catch(error){log('service_request_failed',{path,category:clean(error?.name||'error',80),message:clean(error?.message,240)});return json({error:error?.message||'service_network_unavailable'},error?.status>=400&&error?.status<600?error.status:500)}}};
